    suspend fun `addUa`(`req`: AddUa): AccountInfo
    
    suspend fun `addWatch`(`req`: AddWatch): AccountInfo
    
    suspend fun `createPasskeyKey`(`req`: CreatePasskeyKey): KeyRef
    
