    suspend fun `marks`(`seed`: kotlin.String, `chain`: kotlin.String): List<AccountInfo>
    
    suspend fun `msigState`(`chain`: kotlin.String, `ua`: kotlin.String): MsigState
    
    suspend fun `nextAccount`(`seed`: kotlin.String): kotlin.UInt
    
    suspend fun `pqzDecoyCandidates`(`chain`: kotlin.String): List<kotlin.String>
    
    suspend fun `prepareAcceptMembership`(`req`: AcceptMembership): RegistryWrite?
    
    suspend fun `prepareCompleteRecovery`(`key`: KeyRef, `chain`: kotlin.String, `account`: kotlin.String, `newKey`: SubjectKeyArgs): NativeQuote
    
    suspend fun `prepareInitiateRecovery`(`op`: SmartOp, `account`: kotlin.String, `newKey`: SubjectKeyArgs): Prepared
    
    suspend fun `prepareKemRepair`(`key`: KeyRef, `chain`: kotlin.String, `payer`: KeyRef): RegistryWrite?
    
