    suspend fun `prepareRegister`(`req`: Register): List<RegistryWrite>
    
    suspend fun `prepareSetKemKey`(`key`: KeyRef, `chain`: kotlin.String, `version`: kotlin.ULong, `payer`: KeyRef): RegistryWrite?
    
    suspend fun `prepareSmartAddKey`(`op`: SmartOp, `key`: SubjectKeyArgs): Prepared
    
    suspend fun `prepareSmartCancelNonce`(`op`: SmartOp, `lane`: kotlin.String): Prepared
    
    suspend fun `prepareSmartCancelRecovery`(`op`: SmartOp): Prepared
    
    suspend fun `prepareSmartDeploy`(`key`: KeyRef, `chain`: kotlin.String, `factory`: kotlin.String, `firstKey`: SubjectKeyArgs, `guardian`: kotlin.String): NativeQuote
    
    suspend fun `prepareSmartExecute`(`op`: SmartOp, `call`: SmartCall): Prepared
    
    suspend fun `prepareSmartRemoveKey`(`op`: SmartOp, `index`: kotlin.String): Prepared
    
    suspend fun `prepareSmartRotateKey`(`op`: SmartOp, `index`: kotlin.String, `key`: SubjectKeyArgs): Prepared
    
    suspend fun `prepareSmartSetGuardian`(`op`: SmartOp, `guardian`: kotlin.String): Prepared
    
    suspend fun `prepareSubmitRegistration`(`blob`: RegistrationBlob, `chain`: kotlin.String, `expectedUa`: kotlin.String, `payer`: KeyRef): List<RegistryWrite>
    
    suspend fun `prepareUpdateMsig`(`req`: UpdateMsig): MsigUpdatePlan
    
    suspend fun `quoteRegistryWrite`(`write`: RegistryWrite): SubmitQuote
    
    suspend fun `registerTarget`(`chain`: kotlin.String, `kind`: kotlin.UShort): kotlin.String
    
    suspend fun `registrationBlob`(`key`: KeyRef, `attrs`: RegisterAttrs): RegistrationBlob
    
    suspend fun `registrationOf`(`chain`: kotlin.String, `ua`: kotlin.String): RegistrationState
    
    suspend fun `restore`(`req`: Restore): List<AccountInfo>
    
    suspend fun `signs`(`seed`: kotlin.String, `id`: kotlin.String): kotlin.Boolean
    
    suspend fun `submitRegistryWrite`(`write`: RegistryWrite, `quote`: SubmitQuote): kotlin.String
    
    suspend fun `uaLine`(`chain`: kotlin.String, `ua`: kotlin.String): UaLine
    
    companion object
}

/**
 * Accounts (spec §7).
 */
open class Account: Disposable, AutoCloseable, AccountInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_scaas_sdk_fn_free_account(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_scaas_sdk_fn_clone_account(handle, status)
        }
    }

    
    @Throws(SdkException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `accounts`(`seed`: kotlin.String) : List<AccountInfo> {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_scaas_sdk_fn_method_account_accounts(
                uniffiHandle,
                FfiConverterString.lower(`seed`),
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_scaas_sdk_rust_future_poll_rust_buffer(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_scaas_sdk_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.ffi_scaas_sdk_rust_future_free_rust_buffer(future) },
        // lift function
        { FfiConverterSequenceTypeAccountInfo.lift(it) },
        // Error FFI converter
        SdkException.ErrorHandler,
    )
    }

    
    @Throws(SdkException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `addNative`(`req`: AddNative) : AccountInfo {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_scaas_sdk_fn_method_account_add_native(
                uniffiHandle,
                FfiConverterTypeAddNative.lower(`req`),
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_scaas_sdk_rust_future_poll_rust_buffer(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_scaas_sdk_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.ffi_scaas_sdk_rust_future_free_rust_buffer(future) },
        // lift function
        { FfiConverterTypeAccountInfo.lift(it) },
        // Error FFI converter
        SdkException.ErrorHandler,
    )
    }

    
    @Throws(SdkException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `addUa`(`req`: AddUa) : AccountInfo {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_scaas_sdk_fn_method_account_add_ua(
                uniffiHandle,
                FfiConverterTypeAddUa.lower(`req`),
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_scaas_sdk_rust_future_poll_rust_buffer(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_scaas_sdk_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.ffi_scaas_sdk_rust_future_free_rust_buffer(future) },
        // lift function
        { FfiConverterTypeAccountInfo.lift(it) },
        // Error FFI converter
        SdkException.ErrorHandler,
    )
    }

    
    @Throws(SdkException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `addWatch`(`req`: AddWatch) : AccountInfo {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_scaas_sdk_fn_method_account_add_watch(
                uniffiHandle,
                FfiConverterTypeAddWatch.lower(`req`),
