            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_scaas_sdk_fn_method_preparedorder_chain(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * The order's hash (its typed digest).
     */override fun `id`(): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_scaas_sdk_fn_method_preparedorder_id(
        it,
        _status)
}
    }
    )
    }
    

    override fun `review`(): List<ReviewField> {
