//


/**
 * The SDK (spec §4): the module accessors, events, watching.
 */
public interface SdkInterface {
    
    /**
     * The account module (spec §7).
     */
    fun `account`(): Account
    
    /**
     * The admin module (spec §11).
     */
    fun `admin`(): Admin
    
    /**
     * The confidential module (spec §9).
     */
    fun `confidential`(): Confidential
    
    /**
     * The DEX module (spec §10).
     */
    fun `dex`(): Dex
    
    /**
     * The limits in force.
     */
    fun `limits`(): Limits
    
    /**
     * The operations module (spec §13).
     */
    fun `op`(): Op
    
    suspend fun `stateRev`(): kotlin.ULong
    
    /**
     * A subscription to the SDK's events (spec §14).
     */
    fun `subscribe`(): Subscription
    
    /**
     * The seed module (spec §6).
     */
    fun `vault`(): Vault
    
    /**
     * The wallet module (spec §8).
     */
    fun `wallet`(): Wallet
    
    suspend fun `watch`(`account`: kotlin.String, `chains`: List<kotlin.String>)
    
    companion object
}

/**
