/**
 * Seeds (spec §6).
 */
public interface VaultInterface {
    
    suspend fun `changePassphrase`(`seed`: kotlin.String, `old`: SecretBytes, `new`: SecretBytes)
    
    suspend fun `confirmBackup`(`seed`: kotlin.String)
    
    suspend fun `deriveChild`(`req`: DeriveChild): NewSeed
    
    suspend fun `deriveFromKey`(`req`: DeriveFromKey): NewSeed
    
    suspend fun `deriveFromSignature`(`req`: DeriveFromSignature): NewSeed
    
    suspend fun `disablePrfUnlock`(`seed`: kotlin.String)
    
    suspend fun `enablePasskeyUnlock`(`seed`: kotlin.String, `vaultPassphrase`: SecretBytes)
    
    suspend fun `enablePlatformUnlock`(`seed`: kotlin.String, `vaultPassphrase`: SecretBytes, `policy`: KeyPolicy)
    
    suspend fun `generate`(`req`: Generate): NewSeed
    
    suspend fun `importKey`(`req`: ImportKey): ImportedKey
    
    suspend fun `importWords`(`req`: ImportWords): SeedInfo
    
    /**
     * Root (c)'s typed data for the account `account_hex` and set `set` (spec §6.6).
     */
    fun `keyDerivationTypedData`(`accountHex`: kotlin.String, `set`: kotlin.UInt): kotlin.String
    
    suspend fun `keystoreRollback`(): kotlin.Boolean
    
    /**
     * Locks `seed`: the ids of the hidden sets abandoned with it. A failed call is its error (`Internal`), never an empty
     * answer: the seed is then not known locked.
     */
    suspend fun `lock`(`seed`: kotlin.String): List<kotlin.String>
    
    /**
