 */
data class SignedOpBlob (
    /**
     * 1
     */
    var `v`: kotlin.UInt
    , 
    /**
     * the profile's `chain_uid` (`0x` + 64 hex)
     */
    var `chainUid`: kotlin.String
    , 
    /**
     * `evm`, `soroban`
     */
    var `family`: kotlin.String
    , 
    /**
     * the domain's contract, the token (`0x` + 40 hex; a `C…` on Soroban)
     */
