/**
 * An account row, by shape (spec §6.1), each with its fields in the written order.
 */
sealed class AccountRow {
    
    data class Ua(
        val `id`: kotlin.String, 
        val `name`: kotlin.String, 
        val `kind`: kotlin.ULong, 
        val `account`: kotlin.ULong, 
        val `index`: kotlin.ULong, 
        val `ua`: kotlin.String) : AccountRow()
        
    {
        

        companion object
    }
    
    data class Native(
        val `id`: kotlin.String, 
        val `name`: kotlin.String, 
        val `network`: kotlin.String, 
        val `index`: kotlin.ULong, 
        val `coinType`: kotlin.ULong?, 
        val `change`: kotlin.ULong?, 
        val `path`: kotlin.String?, 
        val `ss58Prefix`: kotlin.ULong?, 
        val `address`: kotlin.String) : AccountRow()
        
    {
        

        companion object
    }
    
    data class Key(
        val `id`: kotlin.String, 
        val `name`: kotlin.String, 
        val `kind`: kotlin.ULong, 
        val `keyData`: kotlin.String, 
        val `credentialId`: kotlin.String?, 
        val `handle`: kotlin.String?, 
        val `ua`: kotlin.String) : AccountRow()
        
    {
        

        companion object
    }
    
    data class Watch(
        val `id`: kotlin.String, 
        val `name`: kotlin.String, 
        val `watch`: kotlin.String) : AccountRow()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAccountRow : FfiConverterRustBuffer<AccountRow>{
    override fun read(buf: ByteBuffer): AccountRow {
        return when(buf.getInt()) {
            1 -> AccountRow.Ua(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> AccountRow.Native(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> AccountRow.Key(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> AccountRow.Watch(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AccountRow) = when(value) {
        is AccountRow.Ua -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterULong.allocationSize(value.`kind`)
                + FfiConverterULong.allocationSize(value.`account`)
                + FfiConverterULong.allocationSize(value.`index`)
                + FfiConverterString.allocationSize(value.`ua`)
            )
        }
        is AccountRow.Native -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterString.allocationSize(value.`network`)
                + FfiConverterULong.allocationSize(value.`index`)
                + FfiConverterOptionalULong.allocationSize(value.`coinType`)
                + FfiConverterOptionalULong.allocationSize(value.`change`)
                + FfiConverterOptionalString.allocationSize(value.`path`)
                + FfiConverterOptionalULong.allocationSize(value.`ss58Prefix`)
                + FfiConverterString.allocationSize(value.`address`)
            )
        }
        is AccountRow.Key -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterULong.allocationSize(value.`kind`)
                + FfiConverterString.allocationSize(value.`keyData`)
                + FfiConverterOptionalString.allocationSize(value.`credentialId`)
                + FfiConverterOptionalString.allocationSize(value.`handle`)
                + FfiConverterString.allocationSize(value.`ua`)
            )
        }
        is AccountRow.Watch -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterString.allocationSize(value.`watch`)
            )
        }
    }

    override fun write(value: AccountRow, buf: ByteBuffer) {
        when(value) {
            is AccountRow.Ua -> {
                buf.putInt(1)
                FfiConverterString.write(value.`id`, buf)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterULong.write(value.`kind`, buf)
                FfiConverterULong.write(value.`account`, buf)
                FfiConverterULong.write(value.`index`, buf)
                FfiConverterString.write(value.`ua`, buf)
                Unit
            }
            is AccountRow.Native -> {
                buf.putInt(2)
                FfiConverterString.write(value.`id`, buf)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterString.write(value.`network`, buf)
                FfiConverterULong.write(value.`index`, buf)
                FfiConverterOptionalULong.write(value.`coinType`, buf)
                FfiConverterOptionalULong.write(value.`change`, buf)
                FfiConverterOptionalString.write(value.`path`, buf)
                FfiConverterOptionalULong.write(value.`ss58Prefix`, buf)
                FfiConverterString.write(value.`address`, buf)
                Unit
            }
            is AccountRow.Key -> {
                buf.putInt(3)
                FfiConverterString.write(value.`id`, buf)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterULong.write(value.`kind`, buf)
                FfiConverterString.write(value.`keyData`, buf)
                FfiConverterOptionalString.write(value.`credentialId`, buf)
                FfiConverterOptionalString.write(value.`handle`, buf)
                FfiConverterString.write(value.`ua`, buf)
                Unit
            }
            is AccountRow.Watch -> {
                buf.putInt(4)
                FfiConverterString.write(value.`id`, buf)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterString.write(value.`watch`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * An authenticator's failure; `Unexpected` is a foreign exception inside the app's implementation.
 */
sealed class AuthException: kotlin.Exception() {
    
    class Refused(
        ) : AuthException() {
        override val message
            get() = ""
    }
    
    class Cancelled(
        ) : AuthException() {
        override val message
            get() = ""
    }
    
    class Unavailable(
        ) : AuthException() {
        override val message
            get() = ""
    }
    
    class Unexpected(
        ) : AuthException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AuthException> {
        override fun lift(error_buf: RustBuffer.ByValue): AuthException = FfiConverterTypeAuthError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAuthError : FfiConverterRustBuffer<AuthException> {
    override fun read(buf: ByteBuffer): AuthException {
        

        return when(buf.getInt()) {
            1 -> AuthException.Refused()
            2 -> AuthException.Cancelled()
            3 -> AuthException.Unavailable()
            4 -> AuthException.Unexpected()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AuthException): ULong {
        return when(value) {
            is AuthException.Refused -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AuthException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AuthException.Unavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AuthException.Unexpected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: AuthException, buf: ByteBuffer) {
        when(value) {
            is AuthException.Refused -> {
                buf.putInt(1)
                Unit
            }
            is AuthException.Cancelled -> {
                buf.putInt(2)
                Unit
            }
            is AuthException.Unavailable -> {
                buf.putInt(3)
                Unit
            }
            is AuthException.Unexpected -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * What a `Consumed` or `Expired` rests on (CLI-RPC-09, owner 2026-11-17, T13 S7; review T26 B-14): the strict majority's agreed
 * read at the `finalized` block, or endpoint 0's alone under `failover`.
 */

enum class Basis {
    
    MAJORITY,
    ONE_ENDPOINT;

    


