/**
 * One delay sentence of a power bit, by name.
 */
sealed class DelaySentence {
    
    /**
     * `atOnce`: the delay is 0, a holder's change applies at once
     */
    object AtOnce : DelaySentence()
    
    
    /**
     * the change applies after `delay` seconds, the longer of the factory's notice period and the token's grant delay
     */
    data class After(
        val `delay`: kotlin.ULong) : DelaySentence()
        
    {
        

        companion object
    }
    
    /**
     * `singleKey`: the holder is a single key
     */
    object SingleKey : DelaySentence()
    
    
    /**
     * `locked`: the bit is locked and the admin is gone; nobody can revoke its holders
     */
    object Locked : DelaySentence()
    
    
    /**
     * a bit of the table without delay sentences
     */
    object NoDelay : DelaySentence()
    
    
    /**
     * a bit the table does not know
     */
    object Unknown : DelaySentence()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDelaySentence : FfiConverterRustBuffer<DelaySentence>{
    override fun read(buf: ByteBuffer): DelaySentence {
        return when(buf.getInt()) {
            1 -> DelaySentence.AtOnce
            2 -> DelaySentence.After(
                FfiConverterULong.read(buf),
                )
            3 -> DelaySentence.SingleKey
            4 -> DelaySentence.Locked
            5 -> DelaySentence.NoDelay
            6 -> DelaySentence.Unknown
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DelaySentence) = when(value) {
        is DelaySentence.AtOnce -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is DelaySentence.After -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`delay`)
            )
        }
        is DelaySentence.SingleKey -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is DelaySentence.Locked -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is DelaySentence.NoDelay -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is DelaySentence.Unknown -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: DelaySentence, buf: ByteBuffer) {
        when(value) {
            is DelaySentence.AtOnce -> {
                buf.putInt(1)
                Unit
            }
            is DelaySentence.After -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`delay`, buf)
                Unit
            }
            is DelaySentence.SingleKey -> {
                buf.putInt(3)
                Unit
            }
            is DelaySentence.Locked -> {
                buf.putInt(4)
                Unit
            }
            is DelaySentence.NoDelay -> {
                buf.putInt(5)
                Unit
            }
            is DelaySentence.Unknown -> {
                buf.putInt(6)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





