/**
 * An SDK event (appended only).
 */
sealed class Event {
    
    data class SeedUnlocked(
        val `seed`: kotlin.String) : Event()
        
    {
        

        companion object
    }
    
    data class SeedLocked(
        val `seed`: kotlin.String) : Event()
        
    {
        

        companion object
    }
    
    data class KeystoreChanged(
        val `rev`: kotlin.ULong) : Event()
        
    {
        

        companion object
    }
    
    data class KeystoreMismatch(
        val `seed`: kotlin.String) : Event()
        
    {
        

        companion object
    }
    
    object KeystoreRollback : Event()
    
    
    data class HiddenOpsAbandoned(
        val `count`: kotlin.UInt) : Event()
        
    {
        

        companion object
    }
    
    /**
     * The subscriber's queue overflowed: `missed` events were dropped for it
     */
    data class Lagged(
        val `missed`: kotlin.ULong) : Event()
        
    {
        

        companion object
    }
    
    /**
     * An operation's state changed (spec §13.4, §13.5): every send result after `submit` arrives here, never as its error.
     */
    data class OpState(
        val `op`: kotlin.String, 
        val `state`: uniffi.scaas_sdk.OpState) : Event()
        
    {
        

        companion object
    }
    
    /**
     * A watched token's balance moved at the profile's final block (spec §14).
     */
    data class BalanceChanged(
        val `account`: kotlin.String, 
        val `chain`: kotlin.String, 
        val `token`: kotlin.String) : Event()
        
    {
        

        companion object
    }
    
    /**
     * A watched account's new history items (spec §8.4), newest first.
     */
    data class HistoryAdded(
        val `account`: kotlin.String, 
        val `chain`: kotlin.String, 
        val `items`: List<uniffi.scaas_sdk.HistoryItem>) : Event()
        
    {
        

        companion object
    }
    
    /**
     * Another process changed `sdk.state` (R17): its `rev` now.
     */
    data class StateChanged(
        val `rev`: kotlin.ULong) : Event()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeEvent : FfiConverterRustBuffer<Event>{
    override fun read(buf: ByteBuffer): Event {
        return when(buf.getInt()) {
            1 -> Event.SeedUnlocked(
                FfiConverterString.read(buf),
                )
            2 -> Event.SeedLocked(
                FfiConverterString.read(buf),
                )
            3 -> Event.KeystoreChanged(
                FfiConverterULong.read(buf),
                )
            4 -> Event.KeystoreMismatch(
                FfiConverterString.read(buf),
                )
            5 -> Event.KeystoreRollback
            6 -> Event.HiddenOpsAbandoned(
                FfiConverterUInt.read(buf),
                )
            7 -> Event.Lagged(
                FfiConverterULong.read(buf),
                )
            8 -> Event.OpState(
                FfiConverterString.read(buf),
                FfiConverterTypeOpState.read(buf),
                )
            9 -> Event.BalanceChanged(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            10 -> Event.HistoryAdded(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterSequenceTypeHistoryItem.read(buf),
                )
            11 -> Event.StateChanged(
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Event) = when(value) {
        is Event.SeedUnlocked -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`seed`)
            )
        }
        is Event.SeedLocked -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`seed`)
            )
        }
        is Event.KeystoreChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`rev`)
            )
        }
        is Event.KeystoreMismatch -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`seed`)
            )
        }
        is Event.KeystoreRollback -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Event.HiddenOpsAbandoned -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`count`)
            )
        }
        is Event.Lagged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`missed`)
            )
        }
        is Event.OpState -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`op`)
                + FfiConverterTypeOpState.allocationSize(value.`state`)
            )
        }
        is Event.BalanceChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`account`)
                + FfiConverterString.allocationSize(value.`chain`)
                + FfiConverterString.allocationSize(value.`token`)
            )
        }
        is Event.HistoryAdded -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`account`)
                + FfiConverterString.allocationSize(value.`chain`)
                + FfiConverterSequenceTypeHistoryItem.allocationSize(value.`items`)
            )
        }
        is Event.StateChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`rev`)
            )
        }
    }

    override fun write(value: Event, buf: ByteBuffer) {
        when(value) {
            is Event.SeedUnlocked -> {
                buf.putInt(1)
                FfiConverterString.write(value.`seed`, buf)
                Unit
            }
            is Event.SeedLocked -> {
                buf.putInt(2)
                FfiConverterString.write(value.`seed`, buf)
                Unit
            }
            is Event.KeystoreChanged -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`rev`, buf)
                Unit
            }
            is Event.KeystoreMismatch -> {
                buf.putInt(4)
                FfiConverterString.write(value.`seed`, buf)
                Unit
            }
            is Event.KeystoreRollback -> {
                buf.putInt(5)
                Unit
            }
            is Event.HiddenOpsAbandoned -> {
                buf.putInt(6)
                FfiConverterUInt.write(value.`count`, buf)
                Unit
            }
            is Event.Lagged -> {
                buf.putInt(7)
                FfiConverterULong.write(value.`missed`, buf)
                Unit
            }
            is Event.OpState -> {
                buf.putInt(8)
                FfiConverterString.write(value.`op`, buf)
                FfiConverterTypeOpState.write(value.`state`, buf)
                Unit
            }
            is Event.BalanceChanged -> {
