    }

    override fun allocationSize(value: InFlight) = 4UL

    override fun write(value: InFlight, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * A key the SDK signs with, by reference (spec §5): the seed's open wallet holds it, or, for [`KeyRef::Key`], the platform's
 * authenticator (a passkey or a secure-element key, a row of the seed: owner 2026-11-19, S1).
 */
sealed class KeyRef {
    
    data class Ua(
        val `seed`: kotlin.String, 
        val `kind`: kotlin.UShort, 
        val `account`: kotlin.UInt, 
        val `index`: kotlin.UInt) : KeyRef()
        
    {
        

        companion object
    }
    
    data class Native(
        val `seed`: kotlin.String, 
        /**
         * a `scaas-ua` network name (`evm` for a payer)
         */
        val `network`: kotlin.String, 
        val `index`: kotlin.UInt) : KeyRef()
        
    {
        

        companion object
    }
    
    /**
     * an imported classical key (spec §6.7, `vault.import_key`): the seed's vault `native-import:<network>:<index>`
     */
    data class Imported(
        val `seed`: kotlin.String, 
        val `network`: kotlin.String, 
        val `index`: kotlin.UInt) : KeyRef()
        
    {
        

        companion object
    }
    
    /**
     * the stored key row `id` of seed `seed` (`AccountRow::Key`: a passkey `webauthn-p256` with its credential id, a
     * secure-element `p256` key with its handle), signing through the `Authenticator` (`external`)
     */
    data class Key(
        val `seed`: kotlin.String, 
        val `id`: kotlin.String) : KeyRef()
        
    {
        

        companion object
    }
    
    /**
     * the `msig` UA `ua` (`0x` + 64 hex) of the profile's registry, signing by the member slots named (CTR-UA-09, CTR-UA-38),
     * each slot's key one this SDK holds; a minimal set of enabled and accepted slots of its current structure (CTR-UA-07,
     * CTR-UA-37, CTR-UA-44). A slot's key is never an `Msig` itself (`Argument`).
     */
    data class Msig(
        val `ua`: kotlin.String, 
        val `slots`: List<uniffi.scaas_sdk.MsigSlot>) : KeyRef()
        
    {
        

        companion object
    }
    
    /**
     * a `bls12381-multi` (`0x0121`) group (plan Task 17): the seed's member key `ua_key(0x0121, account, index)` (EIP-2333:
     * index 0) and the group's key data `d` (`0x` hex, spec 2026-11-19-bls12381-multi §2); the signer's id is the group's
     * UA, its signature the members' aggregate ([`Op::submit_bls_multi`])
     */
    data class BlsMulti(
        val `seed`: kotlin.String, 
        val `account`: kotlin.UInt, 
        val `index`: kotlin.UInt, 
        val `keyData`: kotlin.String) : KeyRef()
        
    {
        

        companion object
    }
    
    /**
     * an operation another party signed and handed off (`Op::import_signed`, spec §27.5 (c)): its signer's subject id (`0x`
     * hex); nothing in this SDK signs for it
     */
    data class Signed(
        val `signer`: kotlin.String) : KeyRef()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeKeyRef : FfiConverterRustBuffer<KeyRef>{
    override fun read(buf: ByteBuffer): KeyRef {
        return when(buf.getInt()) {
            1 -> KeyRef.Ua(
                FfiConverterString.read(buf),
                FfiConverterUShort.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            2 -> KeyRef.Native(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            3 -> KeyRef.Imported(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            4 -> KeyRef.Key(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> KeyRef.Msig(
                FfiConverterString.read(buf),
                FfiConverterSequenceTypeMsigSlot.read(buf),
                )
            6 -> KeyRef.BlsMulti(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> KeyRef.Signed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: KeyRef) = when(value) {
        is KeyRef.Ua -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`seed`)
                + FfiConverterUShort.allocationSize(value.`kind`)
                + FfiConverterUInt.allocationSize(value.`account`)
                + FfiConverterUInt.allocationSize(value.`index`)
            )
        }
        is KeyRef.Native -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`seed`)
                + FfiConverterString.allocationSize(value.`network`)
                + FfiConverterUInt.allocationSize(value.`index`)
            )
        }
        is KeyRef.Imported -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`seed`)
                + FfiConverterString.allocationSize(value.`network`)
                + FfiConverterUInt.allocationSize(value.`index`)
            )
        }
        is KeyRef.Key -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`seed`)
                + FfiConverterString.allocationSize(value.`id`)
            )
        }
        is KeyRef.Msig -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`ua`)
                + FfiConverterSequenceTypeMsigSlot.allocationSize(value.`slots`)
            )
        }
        is KeyRef.BlsMulti -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`seed`)
                + FfiConverterUInt.allocationSize(value.`account`)
                + FfiConverterUInt.allocationSize(value.`index`)
                + FfiConverterString.allocationSize(value.`keyData`)
            )
        }
        is KeyRef.Signed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`signer`)
            )
        }
    }

    override fun write(value: KeyRef, buf: ByteBuffer) {
        when(value) {
            is KeyRef.Ua -> {
                buf.putInt(1)
                FfiConverterString.write(value.`seed`, buf)
                FfiConverterUShort.write(value.`kind`, buf)
                FfiConverterUInt.write(value.`account`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                Unit
            }
            is KeyRef.Native -> {
                buf.putInt(2)
                FfiConverterString.write(value.`seed`, buf)
                FfiConverterString.write(value.`network`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                Unit
            }
            is KeyRef.Imported -> {
                buf.putInt(3)
                FfiConverterString.write(value.`seed`, buf)
                FfiConverterString.write(value.`network`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                Unit
            }
            is KeyRef.Key -> {
                buf.putInt(4)
                FfiConverterString.write(value.`seed`, buf)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is KeyRef.Msig -> {
                buf.putInt(5)
                FfiConverterString.write(value.`ua`, buf)
                FfiConverterSequenceTypeMsigSlot.write(value.`slots`, buf)
                Unit
            }
            is KeyRef.BlsMulti -> {
                buf.putInt(6)
                FfiConverterString.write(value.`seed`, buf)
                FfiConverterUInt.write(value.`account`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                FfiConverterString.write(value.`keyData`, buf)
                Unit
            }
            is KeyRef.Signed -> {
                buf.putInt(7)
                FfiConverterString.write(value.`signer`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





