/**
 * An operation's state (spec §13.5, CLI-SDK-18): terminal only on a chain fact from a decisive read at the profile's final
 * block.
 */
sealed class OpState {
    
    /**
     * the executed event of the operation's digest at or below the final block
     */
    data class Landed(
        val `block`: kotlin.ULong, 
        val `hash`: kotlin.String) : OpState()
        
    {
        

        companion object
    }
    
    /**
     * the lane's nonce spent at the final block without that event; a replaced native send
     */
    data class Consumed(
        val `basis`: uniffi.scaas_sdk.Basis) : OpState()
        
    {
        

        companion object
    }
    
    /**
     * an EVM native send final at or below the final block and reverted (owner 2026-11-18, ruling 4; the node's `reverted`)
     */
    data class Reverted(
        val `block`: kotlin.ULong, 
        val `hash`: kotlin.String) : OpState()
        
    {
        

        companion object
    }
    
    /**
     * `validUntil` below the final block's timestamp while the nonce is unspent
     */
    data class Expired(
        val `basis`: uniffi.scaas_sdk.Basis) : OpState()
        
    {
        

        companion object
    }
    
    /**
     * anything else, with what is known (never an end)
     */
    data class InFlight(
        val `detail`: uniffi.scaas_sdk.InFlight) : OpState()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeOpState : FfiConverterRustBuffer<OpState>{
    override fun read(buf: ByteBuffer): OpState {
        return when(buf.getInt()) {
            1 -> OpState.Landed(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> OpState.Consumed(
                FfiConverterTypeBasis.read(buf),
                )
            3 -> OpState.Reverted(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> OpState.Expired(
                FfiConverterTypeBasis.read(buf),
                )
            5 -> OpState.InFlight(
                FfiConverterTypeInFlight.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: OpState) = when(value) {
        is OpState.Landed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`block`)
                + FfiConverterString.allocationSize(value.`hash`)
            )
        }
        is OpState.Consumed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeBasis.allocationSize(value.`basis`)
            )
        }
        is OpState.Reverted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`block`)
                + FfiConverterString.allocationSize(value.`hash`)
            )
        }
        is OpState.Expired -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeBasis.allocationSize(value.`basis`)
            )
        }
        is OpState.InFlight -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeInFlight.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: OpState, buf: ByteBuffer) {
        when(value) {
            is OpState.Landed -> {
                buf.putInt(1)
                FfiConverterULong.write(value.`block`, buf)
                FfiConverterString.write(value.`hash`, buf)
                Unit
            }
            is OpState.Consumed -> {
                buf.putInt(2)
                FfiConverterTypeBasis.write(value.`basis`, buf)
                Unit
            }
            is OpState.Reverted -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`block`, buf)
                FfiConverterString.write(value.`hash`, buf)
                Unit
            }
            is OpState.Expired -> {
                buf.putInt(4)
                FfiConverterTypeBasis.write(value.`basis`, buf)
                Unit
            }
            is OpState.InFlight -> {
                buf.putInt(5)
                FfiConverterTypeInFlight.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * The `PayMeta` body by schema (pay-meta-tax spec §7.1), named.
 */
sealed class PayBody {
    
    object None : PayBody()
    
    
    data class Note(
        val `note`: kotlin.String) : PayBody()
        
    {
        

        companion object
    }
    
    data class CreditorRef(
        val `creditorRef`: kotlin.String, 
        val `dueDate`: kotlin.ULong) : PayBody()
        
    {
        

        companion object
    }
    
    data class BoundCall(
        val `chainId`: kotlin.String, 
        val `target`: kotlin.String, 
        val `callHash`: kotlin.String) : PayBody()
        
    {
        

        companion object
    }
    
    data class Ciphertext(
        val `ciphertext`: kotlin.String) : PayBody()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePayBody : FfiConverterRustBuffer<PayBody>{
    override fun read(buf: ByteBuffer): PayBody {
        return when(buf.getInt()) {
            1 -> PayBody.None
            2 -> PayBody.Note(
                FfiConverterString.read(buf),
                )
            3 -> PayBody.CreditorRef(
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                )
            4 -> PayBody.BoundCall(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> PayBody.Ciphertext(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PayBody) = when(value) {
        is PayBody.None -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is PayBody.Note -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`note`)
            )
        }
        is PayBody.CreditorRef -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`creditorRef`)
                + FfiConverterULong.allocationSize(value.`dueDate`)
            )
        }
        is PayBody.BoundCall -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`chainId`)
                + FfiConverterString.allocationSize(value.`target`)
                + FfiConverterString.allocationSize(value.`callHash`)
            )
        }
        is PayBody.Ciphertext -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`ciphertext`)
            )
        }
    }

    override fun write(value: PayBody, buf: ByteBuffer) {
        when(value) {
            is PayBody.None -> {
                buf.putInt(1)
                Unit
            }
            is PayBody.Note -> {
                buf.putInt(2)
                FfiConverterString.write(value.`note`, buf)
                Unit
            }
            is PayBody.CreditorRef -> {
                buf.putInt(3)
                FfiConverterString.write(value.`creditorRef`, buf)
                FfiConverterULong.write(value.`dueDate`, buf)
                Unit
            }
            is PayBody.BoundCall -> {
                buf.putInt(4)
                FfiConverterString.write(value.`chainId`, buf)
                FfiConverterString.write(value.`target`, buf)
                FfiConverterString.write(value.`callHash`, buf)
                Unit
            }
            is PayBody.Ciphertext -> {
                buf.putInt(5)
                FfiConverterString.write(value.`ciphertext`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






enum class Policy {
    
    FAILOVER,
    STRICT_MAJORITY;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypePolicy: FfiConverterRustBuffer<Policy> {
    override fun read(buf: ByteBuffer) = try {
        Policy.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: Policy) = 4UL

    override fun write(value: Policy, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





