/**
 * A rescue vault's admin operation (CTR-GOV-25): `seq` the vault's shared order, from 1.
 */
sealed class RescueOp {
    
    /**
     * `setRescuer(seq, newRescuer)`, `new_rescuer` an address (not 0)
     */
    data class SetRescuer(
        val `seq`: kotlin.ULong, 
        val `newRescuer`: kotlin.String) : RescueOp()
        
    {
        

        companion object
    }
    
    /**
     * `rotateAdmin(seq, newAdmin)`, `new_admin` a native UA (not 0)
     */
    data class RotateAdmin(
        val `seq`: kotlin.ULong, 
        val `newAdmin`: kotlin.String) : RescueOp()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeRescueOp : FfiConverterRustBuffer<RescueOp>{
    override fun read(buf: ByteBuffer): RescueOp {
        return when(buf.getInt()) {
            1 -> RescueOp.SetRescuer(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> RescueOp.RotateAdmin(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RescueOp) = when(value) {
        is RescueOp.SetRescuer -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`seq`)
                + FfiConverterString.allocationSize(value.`newRescuer`)
            )
        }
        is RescueOp.RotateAdmin -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`seq`)
                + FfiConverterString.allocationSize(value.`newAdmin`)
            )
        }
    }

    override fun write(value: RescueOp, buf: ByteBuffer) {
        when(value) {
            is RescueOp.SetRescuer -> {
                buf.putInt(1)
                FfiConverterULong.write(value.`seq`, buf)
                FfiConverterString.write(value.`newRescuer`, buf)
                Unit
            }
            is RescueOp.RotateAdmin -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`seq`, buf)
                FfiConverterString.write(value.`newAdmin`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
