        class VaultFormat(message: String) : SdkException(message)
        
        class VaultIo(message: String) : SdkException(message)
        
        class StoreConflict(message: String) : SdkException(message)
        
        class KeystoreMismatch(message: String) : SdkException(message)
        
        class KeystoreRollback(message: String) : SdkException(message)
        
        class AccountUnverified(message: String) : SdkException(message)
        
        class SeedUnknown(message: String) : SdkException(message)
        
        class SeedExists(message: String) : SdkException(message)
        
        class LabelTaken(message: String) : SdkException(message)
        
        class ConfirmationMissing(message: String) : SdkException(message)
        
        class MnemonicInvalid(message: String) : SdkException(message)
        
        class VaultPassphraseWeak(message: String) : SdkException(message)
        
        class DerivationPassphraseShort(message: String) : SdkException(message)
        
        class OriginSignature(message: String) : SdkException(message)
        
        class AuthenticatorRefused(message: String) : SdkException(message)
        
        class ChainUnknown(message: String) : SdkException(message)
        
        class ProfileMismatch(message: String) : SdkException(message)
        
        class FeatureMissing(message: String) : SdkException(message)
        
        class PreparedStale(message: String) : SdkException(message)
        
        class PreparedUnknown(message: String) : SdkException(message)
        
        class OpaqueCallRefused(message: String) : SdkException(message)
        
        class FeeAboveCap(message: String) : SdkException(message)
        
        class GasAboveTxCap(message: String) : SdkException(message)
        
        class PayerDelegated(message: String) : SdkException(message)
        
        class SubmitPathNone(message: String) : SdkException(message)
        
        class VerdictRefused(message: String) : SdkException(message)
        
        class TxTypeRefused(message: String) : SdkException(message)
        
        class KindDisabled(message: String) : SdkException(message)
        
        class RawDigestRefused(message: String) : SdkException(message)
        
        class AppDomainRefused(message: String) : SdkException(message)
        
        class AppPurposeRefused(message: String) : SdkException(message)
        
        class AppSaltMismatch(message: String) : SdkException(message)
        
        class AppHandleForeign(message: String) : SdkException(message)
        
        class AppLabelRefused(message: String) : SdkException(message)
        
        class AppKeyUsage(message: String) : SdkException(message)
        
        class AppArenaFull(message: String) : SdkException(message)
        
        class KemKeyGone(message: String) : SdkException(message)
        
        class ReceiverUnregistered(message: String) : SdkException(message)
        
        class RegistrationUaMismatch(message: String) : SdkException(message)
        
        class RegistrationKindDisabled(message: String) : SdkException(message)
        
        class RegistrationPopInvalid(message: String) : SdkException(message)
        
        class RegistrationKemMissing(message: String) : SdkException(message)
        
        class AbiMismatch(message: String) : SdkException(message)
        
    /**
