/**
 * A slot's key: `KeyRef` without the slots of an `msig` (a slot's key is never one, spec §7).
 */
sealed class SlotKey {
    
    data class Ua(
        val `seed`: kotlin.String, 
        val `kind`: kotlin.UShort, 
        val `account`: kotlin.UInt, 
        val `index`: kotlin.UInt) : SlotKey()
        
    {
        

        companion object
    }
    
    data class Native(
        val `seed`: kotlin.String, 
        val `network`: kotlin.String, 
        val `index`: kotlin.UInt) : SlotKey()
        
    {
        

        companion object
    }
    
    data class Imported(
        val `seed`: kotlin.String, 
        val `network`: kotlin.String, 
        val `index`: kotlin.UInt) : SlotKey()
        
    {
        

        companion object
    }
    
    data class Key(
        val `seed`: kotlin.String, 
        val `id`: kotlin.String) : SlotKey()
        
    {
        

        companion object
    }
    
    /**
     * refused at signing (`Argument`)
     */
    data class Msig(
        val `ua`: kotlin.String) : SlotKey()
        
    {
        

        companion object
    }
    
    /**
     * a `bls12381-multi` group's member key (as `KeyRef::BlsMulti`)
     */
    data class BlsMulti(
        val `seed`: kotlin.String, 
        val `account`: kotlin.UInt, 
        val `index`: kotlin.UInt, 
        val `keyData`: kotlin.String) : SlotKey()
        
    {
        

        companion object
    }
    
    /**
     * another party's signer (as `KeyRef::Signed`, a hand-off): never a slot's key, refused at signing
     */
    data class Signed(
        val `signer`: kotlin.String) : SlotKey()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

