public object FfiConverterTypeSlotKey : FfiConverterRustBuffer<SlotKey>{
    override fun read(buf: ByteBuffer): SlotKey {
        return when(buf.getInt()) {
            1 -> SlotKey.Ua(
                FfiConverterString.read(buf),
