                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                )
            2 -> SlotKey.Native(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            3 -> SlotKey.Imported(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            4 -> SlotKey.Key(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> SlotKey.Msig(
                FfiConverterString.read(buf),
                )
            6 -> SlotKey.BlsMulti(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> SlotKey.Signed(
