                FfiConverterUInt.write(value.`account`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                Unit
            }
            is SlotKey.Native -> {
                buf.putInt(2)
                FfiConverterString.write(value.`seed`, buf)
                FfiConverterString.write(value.`network`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                Unit
            }
            is SlotKey.Imported -> {
                buf.putInt(3)
                FfiConverterString.write(value.`seed`, buf)
                FfiConverterString.write(value.`network`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                Unit
            }
            is SlotKey.Key -> {
                buf.putInt(4)
                FfiConverterString.write(value.`seed`, buf)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is SlotKey.Msig -> {
                buf.putInt(5)
                FfiConverterString.write(value.`ua`, buf)
                Unit
            }
            is SlotKey.BlsMulti -> {
                buf.putInt(6)
                FfiConverterString.write(value.`seed`, buf)
                FfiConverterUInt.write(value.`account`, buf)
                FfiConverterUInt.write(value.`index`, buf)
