/**
 * The call of a `SmartKeyAccount`'s `Execute` (spec §13.2): decoded, or opaque under the marker.
 */
sealed class SmartCall {
    
    /**
     * an ERC-20 `transfer(to, amount)` of `token` held by the account
     */
    data class Transfer(
        val `token`: kotlin.String, 
        val `to`: kotlin.String, 
        val `amount`: kotlin.String) : SmartCall()
        
    {
        

        companion object
    }
    
    /**
     * `account.initiateRecovery(key)`: the signer's account is `account`'s guardian (CTR-ACC-03)
     */
    data class InitiateRecovery(
        val `account`: kotlin.String, 
        val `key`: uniffi.scaas_sdk.SubjectKeyArgs) : SmartCall()
        
    {
        

        companion object
    }
    
    /**
     * any other call: `OpaqueCallRefused` without the marker
     */
    data class Opaque(
        val `target`: kotlin.String, 
        val `value`: kotlin.String, 
        val `data`: kotlin.String, 
        val `allow`: uniffi.scaas_sdk.AllowOpaqueCall?) : SmartCall()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSmartCall : FfiConverterRustBuffer<SmartCall>{
    override fun read(buf: ByteBuffer): SmartCall {
        return when(buf.getInt()) {
