    override fun write(value: SmartCall, buf: ByteBuffer) {
        when(value) {
            is SmartCall.Transfer -> {
                buf.putInt(1)
                FfiConverterString.write(value.`token`, buf)
                FfiConverterString.write(value.`to`, buf)
                FfiConverterString.write(value.`amount`, buf)
